// Function.prototype.bind, call and apply on builtin static functions in
// JavaScript: Buffer, Math, String and JSON.
'use strict';
var byteLength = Buffer.byteLength.bind(Buffer);
var max = Math.max.bind(null, 10);
var fromCodes = String.fromCharCode.bind(String, 104);
var stringify = JSON.stringify.bind(JSON);
var parse = JSON.parse.bind(JSON);
var compare = Buffer.compare.bind(Buffer);

exports.report = function report() {
  return [
    byteLength('héllo'),
    byteLength('héllo', 'latin1'),
    byteLength('abcd', 'hex'),
    byteLength('héllo', 'not-an-encoding'),
    byteLength(''),
    byteLength(Buffer.from([1, 2, 3])),
    max(3, 42),
    max(),
    Math.min.call(null, 4, 2),
    Math.abs.apply(null, [-7]),
    fromCodes(105, 33),
    String.fromCharCode.apply(null, [111, 107]),
    stringify({ a: [1, 2] }),
    stringify({ b: 1 }, null, 2),
    compare(Buffer.from('a'), Buffer.from('b')),
    parse('{"n":1}').n,
    JSON.stringify(parse('[1,2]', function (key, value) {
      return typeof value === 'number' ? value * 10 : value;
    })),
  ];
};

exports.badLength = function badLength() {
  try {
    byteLength(42);
    return 'no error';
  } catch (error) {
    return error.code + ' ' + error.name;
  }
};
